import { compile } from 'svelte/compiler';
import {
	ENRICHED_IR_VERSION,
	type EnrichedComponent,
	type EnrichedEventRecord,
	type EnrichedGraphBinding,
	type EnrichedIR,
	type SerializableAstNode,
	type StaticAttribute,
	type SyncPolicy,
	type TemplateNode,
} from '@frameless/compiler';
import {
	arrow,
	call,
	containsIdentifierFrom,
	type Expression,
	expression,
	expressionStatement,
	identifier,
	indentContinuation,
	type Node,
	printExpression,
	printStatements,
	type Statement,
	tsFunctionType,
	tsKeywordType,
	tsPropertySignature,
	tsTypeAnnotation,
	tsTypeLiteral,
	tsTypeParameterInstantiation,
	tsTypeReference,
	variable,
	walk,
} from './estree.ts';

type StateBinding = EnrichedGraphBinding & { readonly kind: 'state' };

type EmitContext = {
	readonly component: EnrichedComponent;
	readonly eventsById: ReadonlyMap<string, EnrichedEventRecord>;
	/**
	 * Names Svelte treats as reactive at component top level - `$props()`
	 * destructurings, `$state` locals and `$derived` locals. Reading one of
	 * these outside a closure is what raises `state_referenced_locally`.
	 */
	readonly reactiveNames: Set<string>;
	readonly usedApis: Set<SvelteApi>;
	/** Elements that received a sanctioned `svelte-ignore`, by warning code. */
	readonly suppressed: Set<string>;
	/**
	 * Host node id -> the `bind:this` target name, for every `ElementHandleBinding`
	 * this component owns. Empty for every scenario in the corpus, which is what
	 * keeps the emitted bytes of the eight goldens unmoved.
	 */
	readonly handleHosts: ReadonlyMap<string, string>;
	/**
	 * Host node id -> the `{@attach ...}` target name, for every host this
	 * component declares an `attach=` behavior on. Empty for every scenario in the
	 * corpus, which is what keeps the emitted bytes of the eight goldens unmoved.
	 */
	readonly behaviorHosts: ReadonlyMap<string, string>;
	readonly behaviorPlans: readonly SvelteBehaviorPlan[];
	/**
	 * STEP 5. Local name -> emitted `.svelte` specifier, one entry per
	 * `ModuleImport` that resolves to a `.tsrx` module. A `component-reference`
	 * may only name a key of this map: this lane has NO in-file component
	 * declaration, so a reference into the module's own scope is refused rather
	 * than lowered. See the lane-limit note on `emit`.
	 */
	readonly componentImports: ReadonlyMap<string, string>;
};

type SvelteApi = 'untrack';

/**
 * Void elements are emitted WITHOUT the self-closing slash.
 *
 * MEASURED, not stylistic. The template printer keeps sibling boundaries free
 * of whitespace by moving a line break to just before an element's final `>`
 * (see `joinSiblings`). That only works when every element chunk ends with a
 * bare `>`; `<input ... />` would put the break between the `/` and the `>`,
 * which is not a self-closing start tag. `<input>` is standard HTML for a void
 * element and Svelte 5 accepts it. Non-void tags are never self-closed either -
 * Svelte 5 warns `element_invalid_self_closing_tag` on `<span />`.
 */
const VOID_ELEMENTS = new Set([
	'area',
	'base',
	'br',
	'col',
	'embed',
	'hr',
	'img',
	'input',
	'link',
	'meta',
	'param',
	'source',
	'track',
	'wbr',
]);

/**
 * The ONLY Svelte warning codes this emitter is allowed to suppress, and the
 * only tags it will suppress them at.
 *
 * Both codes are observations about the AUTHORED template - the IR declares a
 * click handler on a `<form>` - not about the lowering. A faithful emitter
 * cannot remove them and must not silently ignore them either, so they are
 * suppressed at the emission site with Svelte's own sanctioned annotation, the
 * list is fixed here, and `assertCompilesClean` proves the suppression is
 * EXACTLY right in both directions: a code that would not have fired is a
 * redundant suppression and throws, and a code that fires without a suppression
 * throws too.
 */
export const SANCTIONED_SVELTE_IGNORE_CODES = [
	'a11y_click_events_have_key_events',
	'a11y_no_noninteractive_element_interactions',
] as const;
const A11Y_EVENT_HOST_TAGS = new Set(['form']);

/** Column budget for keeping a start tag on one line. A tab counts as four. */
const PRINT_WIDTH = 100;

function exactKeys(construct: string, value: object, allowed: readonly string[]): void {
	const unknown = Object.keys(value).filter((key) => !allowed.includes(key));
	if (unknown.length) throw new Error(`${construct} has unknown semantic field: ${unknown[0]}`);
}

/**
 * NESTED EXACTNESS. ADDED BY T010 AFTER IT WAS MEASURED MISSING, NOT ASSUMED.
 *
 * Every other allowlist in `validateEnrichedIr` guards a top-level or one-deep
 * construct, and this lane's anti-drift probe plants its unknown field on
 * `EnrichedIR` - which every lane already caught. MEASURED at 127a75b, before
 * this function existed: a key planted on a `PropDestructuringEntry` was
 * accepted by qwik, svelte, vue AND angular with BYTE-IDENTICAL output across
 * all eight goldens, while react and solid threw. Four validators had simply
 * never looked this deep, and that asymmetry is why IR-8's `type` could be
 * added believing all six agreed. The probe was aimed one level too high.
 *
 * `type` and `optional` are IR-8: ADMITTED AND SHAPE-CHECKED HERE, DELIBERATELY
 * NOT PRINTED. Admitting a key without checking its shape would trade one blind
 * spot for another, so a `type` that is not an AST node is rejected by name too,
 * and so is an `optional` that is not a boolean.
 *
 * `optional` IS ALSO CHECKED AGAINST `type`, not just in isolation. The two are
 * read from ONE `TSPropertySignature` at the compiler's only supply site, so an
 * `optional` arriving WITHOUT a `type` did not come from source - it is
 * requiredness synthesized somewhere downstream, which is precisely the
 * invention this phase refuses. This lane rejects that pairing even though it
 * prints neither field, because a validator that only guards what it consumes
 * is how the nested blind spot arose in the first place.
 */
function validatePropEntries(entries: EnrichedIR['components'][number]['props']['entries']): void {
	for (const entry of entries) {
		exactKeys('PropDestructuringEntry', entry, [
			'sourceName',
			'localName',
			'path',
			'alias',
			'graphNodeId',
			'defaultValue',
			'type',
			'optional',
		]);
		if (
			entry.type !== undefined &&
			(typeof entry.type !== 'object' ||
				entry.type === null ||
				typeof (entry.type as { type?: unknown }).type !== 'string')
		)
			throw new Error(
				`PropDestructuringEntry has malformed type annotation AST: ${entry.localName}`,
			);
		if (entry.optional !== undefined && typeof entry.optional !== 'boolean')
			throw new Error(
				`PropDestructuringEntry has malformed optional flag: ${entry.localName}`,
			);
		if (entry.optional !== undefined && entry.type === undefined)
			throw new Error(
				`PropDestructuringEntry declares optionality without a type annotation: ${entry.localName}`,
			);
	}
}

/** Fail closed at the public emitter boundary before constructing output. */
/**
 * SHAPE-CHECKS THE TWO RECORD FAMILIES THIS LANE STARTED CONSUMING AT STEP 3.
 *
 * Before refs landed here, `validateEnrichedIr` checked only that
 * `elementHandleBindings` and `handleCalls` were ARRAYS - the family loop above -
 * because the emitter refused any IR that carried one. That was survivable while
 * the records were unreachable. It is not survivable now: this is the same defect
 * class T003 measured and T010 closed one level up, where four lanes accepted a
 * field planted on a nested `PropDestructuringEntry` with byte-identical output
 * while react and solid threw. React validates both families key-by-key
 * (`packages/frameworks/react/src/emitter/index.ts`, the inline `keys` closure);
 * this lane now does too, so a field added to either record fails HERE, by name,
 * rather than being silently dropped on the floor by a lane that consumes it.
 *
 * `handleForwards` is deliberately NOT checked here: this lane still refuses it
 * outright in `emit`, so it remains unreachable and a checker for it would assert
 * over a path that cannot be taken. It is Step 5's to open and Step 5's to
 * validate. `behaviors` WAS in that sentence until Step 4 opened it; it is now
 * checked by `validateBehaviorRecords` below.
 */
function validateHandleRecords(ir: EnrichedIR): void {
	const componentIds = new Set(ir.components.map((component) => component.id));
	const eventIds = new Set(ir.records.events.map((event) => event.id));
	const handleIds = new Set<string>();
	for (const binding of ir.records.elementHandleBindings) {
		exactKeys('ElementHandleBinding', binding, [
			'id',
			'handleName',
			'componentId',
			'hostNodeId',
		]);
		if (
			typeof binding.id !== 'string' ||
			typeof binding.handleName !== 'string' ||
			typeof binding.hostNodeId !== 'string'
		)
			throw new Error('ElementHandleBinding has malformed construct');
		if (!componentIds.has(binding.componentId))
			throw new Error(`ElementHandleBinding has dangling componentId: ${binding.componentId}`);
		handleIds.add(binding.id);
	}
	for (const call of ir.records.handleCalls) {
		exactKeys('HandleCallRecord', call, [
			'handleBindingId',
			'componentId',
			'method',
			'arguments',
			'optional',
			'eventId',
			'site',
			'order',
		]);
		if (
			typeof call.handleBindingId !== 'string' ||
			typeof call.method !== 'string' ||
			!Array.isArray(call.arguments) ||
			typeof call.optional !== 'boolean' ||
			(call.eventId !== undefined && typeof call.eventId !== 'string') ||
			typeof call.order !== 'number'
		)
			throw new Error('HandleCallRecord has malformed construct');
		if (!componentIds.has(call.componentId))
			throw new Error(`HandleCallRecord has dangling componentId: ${call.componentId}`);
		if (!handleIds.has(call.handleBindingId))
			throw new Error(
				`HandleCallRecord has dangling ElementHandleBinding: ${call.handleBindingId}`,
			);
		if (call.eventId !== undefined && !eventIds.has(call.eventId))
			throw new Error(`HandleCallRecord has dangling event: ${call.eventId}`);
	}
}

import { readFile } from 'node:fs/promises';
import { buildEnrichedIr, type EnrichedIR } from '@frameless/compiler';
import { compile } from 'svelte/compiler';
import { resolve } from 'pathe';
import { describe, expect, test } from 'vitest';
import { emit, validateEnrichedIr } from '../src/emitter/index.ts';
import { formatEmitted } from '../src/format-emitted.ts';
import {
	COMPOSITION_EXTENSION,
	compositionFixtures,
	emitCompositionFixture,
} from '../scripts/regenerate-composition.ts';

/**
 * STEP 5, COMPOSITION - the Svelte half.
 *
 * WHAT THIS LANE'S OWN CHECKER CAN AND CANNOT SEE, stated up front so no green
 * below is over-read: `svelte/compiler`'s `compile()` reports WARNINGS AND
 * SYNTAX, NOT TYPES, and it runs inside `emit` already, so every successful
 * `emit` below carries a four-mode clean compile with it. There is no type-level
 * instrument in this package at all - `svelte-check` is coupled to
 * `demos/svelte-official`'s separate install - and NO CLAIM BELOW RESTS ON ONE.
 */
const PACKAGE_ROOT = resolve(import.meta.dirname, '..');

async function ir(name: string): Promise<EnrichedIR> {
	const filename = `test/composition-fixtures/${name}.tsrx`;
	return buildEnrichedIr({
		filename,
		source: await readFile(resolve(PACKAGE_ROOT, filename), 'utf8'),
	});
}

async function irFrom(source: string): Promise<EnrichedIR> {
	return buildEnrichedIr({ filename: 'test/composition-fixtures/probe.tsrx', source });
}

const MODES = [
	{ generate: 'client', dev: true },
	{ generate: 'client', dev: false },
	{ generate: 'server', dev: true },
	{ generate: 'server', dev: false },
] as const;

function warningCodes(source: string): string[] {
	const codes = new Set<string>();
	for (const { generate, dev } of MODES)
		for (const warning of compile(source, { filename: 'Probe.svelte', generate, dev }).warnings)
			codes.add(warning.code);
	return [...codes].sort();
}

/** Two components in ONE module - the shape this lane cannot express. */
const MULTI_COMPONENT = `function Frame({ children }) @{
	<section data-frame>{children}</section>
}

export function SlotPage() @{
	<Frame><strong data-projected-node>Projected composition</strong></Frame>
}`;

describe('Svelte composition', () => {
	test('projects children with {@render} and imports the sibling .svelte module', async () => {
		const panel = emit(await ir('M1-panel'));
		// `{@render}` is the ONLY Svelte 5 construct that invokes a snippet, and the
		// implicit `children` prop is the only place a component's child content
		// arrives - a singleton sanctioned set, so the six-gate procedure has nothing
		// to decide, exactly as T005 recorded for `bind:this`.
		expect(panel).toContain('let { label, children } = $props();');
		expect(panel).toContain('{@render children?.()}');

		const page = emit(await ir('M2-page'));
		// A `.svelte` module's component is its DEFAULT export, so the IR's NAMED
		// `ComponentExport` is honoured by the DEFAULT import here. That is a property
		// of the target format, and it is the same divergence this lane's `emit`
		// header already records for the export side.
		expect(page).toContain("import Panel from './M1-panel.svelte';");
		expect(page).toContain("<Panel label={'Composed'}");
		expect(page).toContain('</Panel>');
	});

	test('generated-composition is fresh from its fixtures', async () => {
		for (const fixture of compositionFixtures)
			expect(
				await readFile(
					resolve(PACKAGE_ROOT, 'generated-composition', `${fixture}${COMPOSITION_EXTENSION}`),
					'utf8',
				),
			).toBe(await emitCompositionFixture(fixture));
	});

	/**
	 * THE LANE LIMIT, PINNED. A `.svelte` file declares exactly ONE component, and
	 * the corpus's own composition fixtures pack several into one module - C1-slot
	 * here, and `demos/composition-kit/src/dashboard.tsrx` packs three - so this
	 * refusal is load-bearing rather than theoretical. It is RECORDED, not forced:
	 * the nearest construct is a snippet, and a snippet body is template-only,
	 * cannot declare `$state`, cannot receive `$props()` and has no lifecycle, so a
	 * component with its own state has no snippet spelling at all.
	 */
	test('refuses a multi-component module by name', async () => {
		await expect(irFrom(MULTI_COMPONENT).then(emit)).rejects.toThrow(
			/multi-component module \(Frame, SlotPage\).*a \.svelte file declares exactly one component/s,
		);
	});

	test('refuses a same-module component reference at the printer too', async () => {
		// The front gate and the template printer refuse the same thing, so a
		// self-reference cannot reach the printer even if the front gate is widened.
		const artifact = await irFrom(MULTI_COMPONENT);
		const single = structuredClone(artifact) as any;
		single.components = [single.components[1]];
		expect(() => emit(single)).toThrow(/same-module component reference \(Frame\)/);
	});

	test('refuses a shared construct by its own name, not as "composition"', async () => {
		const artifact = (await ir('M2-page')) as any;
		const shared = structuredClone(artifact);
		shared.records.sharedInstances = [
			{ definitionId: 'shared:0', componentId: shared.components[0].id, localName: 'x' },
		];
		expect(() => emit(shared)).toThrow(/does not support shared constructs/);
	});

	/**
	 * `{@render children()}` versus `{@render children?.()}` - and the ruling came
	 * from the RUNTIME SEMANTICS, because no diagnostic distinguishes them.
	 * MEASURED here on every run: both forms compile with an EMPTY warning set in
	 * all four client x server, dev x prod modes. The optional call is emitted
	 * because the unguarded form THROWS when a parent passes no children, while
	 * React's `{children}` and Solid's `{props.children}` render nothing - so the
	 * unguarded form would make this lane diverge from the oracle on exactly the
	 * case the other five treat as empty.
	 */
	test('neither {@render} form warns, so the ruling is not a diagnostic', () => {
		const guarded =
			'<script lang="ts">\n\tlet { children } = $props();\n</script>\n\n<div>{@render children?.()}</div>\n';
		const unguarded = guarded.replace('children?.()', 'children()');
		expect(warningCodes(guarded)).toEqual([]);
		expect(warningCodes(unguarded)).toEqual([]);
		// Calibration: this instrument CAN go red, so the two empties above are not vacuous.
		expect(warningCodes('<div onclick={() => {}}>x</div>\n')).toContain(
			'a11y_click_events_have_key_events',
		);
	});

	test('names an unknown field on every composition record this step made reachable', async () => {
		const page = await ir('M2-page');
		const panel = await ir('M1-panel');

		const reference = structuredClone(page) as any;
		reference.components[0].template[0].slotted = true;
		expect(() => validateEnrichedIr(reference)).toThrow(
			/TemplateComponentReference has unknown semantic field: slotted/,
		);
		expect(() => emit(reference)).toThrow(/unknown semantic field: slotted/);

		const prop = structuredClone(page) as any;
		prop.components[0].template[0].props[0].reactive = true;
		expect(() => validateEnrichedIr(prop)).toThrow(
			/ComponentPropExpression has unknown semantic field: reactive/,
		);

		const projection = structuredClone(panel) as any;
		projection.components[0].template[0].children[1].children[0].fallback = [];
		expect(projection.components[0].template[0].children[1].children[0].kind).toBe(
			'default-slot-projection',
		);
		expect(() => validateEnrichedIr(projection)).toThrow(
			/TemplateDefaultSlotProjection has unknown semantic field: fallback/,
		);

		// LAWFUL IR IS GREEN, so the three rejections above are not green by accident.
		expect(() => validateEnrichedIr(page)).not.toThrow();
		expect(() => validateEnrichedIr(panel)).not.toThrow();
	});

	test('refuses an import that does not resolve to a .tsrx module', async () => {
		const artifact = structuredClone(await ir('M2-page')) as any;
		artifact.imports[0].resolvesTo = undefined;
		expect(() => emit(artifact)).toThrow(/ModuleImport cannot be lowered/);
	});

	test('formats to the committed bytes', async () => {
		expect(formatEmitted(emit(await ir('M1-panel')))).toBe(
			await readFile(
				resolve(PACKAGE_ROOT, 'generated-composition/M1-panel.svelte'),
				'utf8',
			),
		);
	});
});
import { readdir, readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import ngPlugin from '@angular-eslint/eslint-plugin';
import tplPlugin from '@angular-eslint/eslint-plugin-template';
import * as templateParser from '@angular-eslint/template-parser';
import { BindingType, parseTemplate } from '@angular/compiler';
import * as tsParser from '@typescript-eslint/parser';
import { ESLint } from 'eslint';
import type { EnrichedIR } from '@frameless/compiler';
import { dirname, normalize, relative, resolve } from 'pathe';

export type DossierRef =
	// Standalone single-file component, class named from the IR's exportedName,
	// and BOTH arbiters - @angular/compiler parseTemplate and @angular-eslint.
	| 'frameless-angular-v1 T002 ruling 4 (both arbiters, compiler first)'
	// onTrace is an @Input, never an @Output/EventEmitter: emit() takes ONE value
	// and the corpus calls onTrace with two AND three positional arguments.
	| 'frameless-angular-v1 T002 ruling 2 (onTrace is an @Input)'
	// IR-1/IR-2: no bindable prop kind and no emit concept. Two-way binding is out
	// of scope on two independent axes.
	| 'frameless-angular-v1 T002 also ruled (IR-1/IR-2)'
	// IR-5: two declared actions, emitted as ordinary in-body statements.
	// stopPropagation fails closed rather than growing an untested path.
	| 'frameless-angular-v1 T002 also ruled (IR-5)'
	// IR-7: purity is never asserted while an Angular getter is re-evaluated on
	// every change-detection pass. Conservative syntactic guard, not a proof.
	| 'frameless-angular-v1 T002 also ruled (IR-7)'
	// IR-4 deferred, version corollary NOT amended: the emitted form set is an
	// explicit allowlist and the lane's version floor is the max over it.
	| 'frameless-angular-v1 T002 also ruled (IR-4 baseline form inventory)'
	// SETTLED, no longer held out. T005 re-ran all six gates against this landed
	// lane: decorator-vs-signal is DENIED at G5, and G6 FAILs, so nothing but this
	// policy pins the form. Worked example 11 in docs/emitter-idiom-policy.md.
	| 'frameless-angular-v1 T005 (decorator-vs-signal, DENIED at G5 and G6)'
	// OnPush is the Angular 22 DEFAULT, so emitting changeDetection at all is an
	// explicit opt-out the applied arbiter reports.
	| 'frameless-angular-v1 T003a ruling 2 (OnPush is the Angular 22 default)'
	// The whitespace layout the template printer depends on, MEASURED at 22.0.8.
	| 'frameless-angular-v1 T003 measurement M1'
	// Qwik's artifact-required policy, transposed: fail closed on persistence.
	| 'T002-qwik-architecture D8'
	// The THIRD-PARTY arbiter. Every policy above encodes what WE decided; these
	// encode what the Angular team decided.
	| 'frameless-angular-v1 T003 lint arbiter';

export type GatePolicy = {
	readonly id: string;
	readonly dossierRef: DossierRef;
	readonly requiresArtifact?: true;
};
export type GateViolation = {
	readonly file: string;
	readonly policy: string;
	readonly dossierRef: DossierRef;
	readonly message: string;
	readonly line: number | null;
};
export type GateResult = {
	readonly files: readonly string[];
	readonly policies: readonly GatePolicy[];
	readonly violations: readonly GateViolation[];
	readonly unevaluated: ReadonlyArray<{
		readonly policy: string;
		readonly reason: 'requires-artifact';
	}>;
};

type Node = Record<string, any>;

const PACKAGE_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const GENERATED_HEADER = '// @generated by @frameless/angular';

function persistenceArtifactPolicy() {
	const policy = {
		id: 'persistence-render-lowering',
		dossierRef: 'T002-qwik-architecture D8',
	} as const;
	Object.defineProperty(policy, 'requiresArtifact', { enumerable: false, value: true });
	return policy as typeof policy & { readonly requiresArtifact: true };
}

// ---------------------------------------------------------------------------
// the third-party arbiter
// ---------------------------------------------------------------------------

/**
 * THE APPLIED SET IS DERIVED, NOT HAND-PICKED, AND THAT IS THE WHOLE POINT.
 *
 * `frameless-angular-v1` T002 ruling 4 modelled this gate on the Svelte one,
 * which consumes `eslint-plugin-svelte`'s `configs.recommended` - a
 * THIRD-PARTY-AUTHORED applied set, which is what makes an arbiter genuinely
 * independent: WE did not choose which rules judge us. T003 then REFUTED THAT
 * RULING'S PREMISE by measurement: `@angular-eslint/eslint-plugin` exports only
 * `rules` (50) and `@angular-eslint/eslint-plugin-template` only `processors` and
 * `rules` (41). NEITHER PUBLISHES A CONFIG. The presets live solely in the
 * `angular-eslint` META package, which T002's own stop_if forbids for a
 * measured reason - see `WHY_THE_META_PACKAGE_IS_NOT_USED`.
 *
 * T003a's answer, and the reason the conclusion survives STRONGER than the
 * premise: every `@angular-eslint` rule carries its OWN membership flag,
 * `meta.docs.recommended === 'recommended'`, and the meta package's published
 * preset is GENERATED FROM THAT SAME METADATA - its header reads, verbatim,
 * "DO NOT EDIT THIS FILE / In order to update this config, please run
 * `pnpm update-rule-configs`". So deriving here is not transcription and not
 * reconstruction: it is running UPSTREAM'S OWN GENERATOR against UPSTREAM'S OWN
 * SOURCE OF TRUTH, already sitting inside the two permitted leaf packages. A rule
 * upstream adds to `recommended` arrives here automatically, which is exactly the
 * property a transcribed set would fake.
 */
function recommendedRules(prefix: string, rules: Readonly<Record<string, unknown>>): string[] {
	return Object.entries(rules)
		.filter(
			([, rule]) =>
				(rule as { meta?: { docs?: { recommended?: unknown } } }).meta?.docs?.recommended ===
				'recommended',
		)
		.map(([name]) => `${prefix}${name}`)
		.sort();
}

/** The 12 of 50 TypeScript rules upstream's own metadata marks `recommended`. */
export const ANGULAR_ESLINT_TS_RULES_DERIVED: readonly string[] = recommendedRules(
	'@angular-eslint/',
	ngPlugin.rules as unknown as Record<string, unknown>,
);

/** The 4 of 41 template rules upstream's own metadata marks `recommended`. */
export const ANGULAR_ESLINT_TEMPLATE_RULES_DERIVED: readonly string[] = recommendedRules(
	'@angular-eslint/template/',
	tplPlugin.rules as unknown as Record<string, unknown>,
);

export type AddedEslintRule = {
	readonly rule: string;
	readonly severity: 'error' | 'warn';
	readonly reason: string;
};

/**
 * THE ONE MEASURED GAP BETWEEN THE DERIVATION AND UPSTREAM'S PUBLISHED PRESET,
 * AND ITS DIRECTION IS WHAT MAKES IT SAFE.
 *
 * `use-lifecycle-interface` IS in upstream's published `ts-recommended` at
 * severity `warn`, and its own `meta.docs.recommended` is `undefined`. The
 * derivation therefore yields 12 where upstream publishes 13, so the applied set
 * is DERIVED UNION ONE RECORDED ADDITION.
 *
 * NOTE THE DIRECTION: the only frameless-authored delta ADDS a rule, and there
 * are ZERO omissions. AN ADDITIONS-ONLY DELTA CANNOT BE USED TO MAKE A CORPUS
 * GREEN, which is precisely what keeps the independence property intact. The
 * `frameless-angular-v1` T003a dissent records the residual risk honestly: if
 * upstream adds a SECOND warn-tier rule the derivation misses it silently, and
