// ---------------------------------------------------------------------------
// the two ASTs this gate reads
// ---------------------------------------------------------------------------

type Parsed = {
	/** The emitted module's TypeScript AST. */
	readonly module: Node;
	/** The exported component class. */
	readonly component: Node | null;
