		component,
		metadata: metadata?.type === 'ObjectExpression' ? metadata : null,
		template,
		templateLine: literal ? (lineOfTs(literal) ?? 1) : 1,
		templateNodes: (parsedTemplate?.nodes ?? []) as Node[],
