	violations.push(...signalViolations(file, parsed));
	violations.push(...twoWayViolations(file, parsed));
	violations.push(...outputViolations(file, parsed));
	violations.push(...changeDetectionViolations(file, parsed));
	violations.push(...stopPropagationViolations(file, parsed));
